function extractMeetCode_(input) {
  var s = String(input || '').trim();
  if (!s) return '';
  var m = s.match(/meet\.google\.com\/([a-z]{3}-[a-z]{4}-[a-z]{3})/i);
  if (m) return m[1].toLowerCase();
  if (/^[a-z]{3}-[a-z]{4}-[a-z]{3}$/i.test(s)) return s.toLowerCase();
  return '';
}

